// The time in Nixie tubes: four glass tubes on a walnut base, each with the
// lit digit glowing in neon over the cold cathodes and the anode mesh, two
// neon dots between the hours and the minutes, and the date engraved on a
// brass plate. It draws on the minute.
import { WEEKDAYS, MONTHS, two, secondsToNextMinute } from './time'

const GLOWS: Record<string, { core: string; glow: string; edge: string }> = {
  orange: { core: '#ffe2b8', glow: '#ff7a1f', edge: '#ffad5c' },
  blue: { core: '#e4f7ff', glow: '#2fa8ff', edge: '#7fd0ff' },
  green: { core: '#e8ffee', glow: '#24e07a', edge: '#7dffb0' },
}

// Behind the lit digit, the unlit cathodes a tube is built from.
const COLD = ['8', '0', '3', '6']

function tube(id: string, x: number, y: number, w: number, h: number, digit: string, glow: any) {
  const f = (n: number) => n.toFixed(1)
  const r = w / 2
  const glass = `M${f(x)} ${f(y + h)} V${f(y + r)} A${f(r)} ${f(r)} 0 0 1 ${f(x + w)} ${f(y + r)} V${f(y + h)} Z`
  const size = h * 0.56
  const cx = x + w / 2
  const baseline = y + h * 0.66
  // The anode mesh: a diamond lattice, kept inside the glass.
  const mesh = []
  const meshTop = y + h * 0.2
  const meshBottom = y + h * 0.8
  const left = x + w * 0.1
  const right = x + w * 0.9
  const slope = 0.6
  const step = w / 6
  const stroke = Math.max(0.6, w * 0.006)
  for (let k = -8; k <= 8; k++) {
    for (const dir of [1, -1]) {
      // x = start + dir * slope * (yy - meshTop), clipped to [left, right].
      const start = (dir > 0 ? left : right) + k * step
      let y0 = meshTop
      let y1 = meshBottom
      const xAt = (yy: number) => start + dir * slope * (yy - meshTop)
      const yAt = (xx: number) => meshTop + (xx - start) / (dir * slope)
      if (xAt(y0) < left) y0 = Math.max(y0, yAt(left))
      if (xAt(y0) > right) y0 = Math.max(y0, yAt(right))
      if (xAt(y1) < left) y1 = Math.min(y1, yAt(left))
      if (xAt(y1) > right) y1 = Math.min(y1, yAt(right))
      if (y1 - y0 < 1) continue
      mesh.push(<line x1={xAt(y0)} y1={y0} x2={xAt(y1)} y2={y1} stroke="#8c6f58" strokeWidth={stroke} opacity={0.2} />)
    }
  }
  const lit = digit !== ' '
  return (
    <g>
      <linearGradient id={`${id}-glass`} gradientUnits="userSpaceOnUse" x1={x} y1="0" x2={x + w} y2="0">
        <stop offset="0" stopColor="#ffffff" stopOpacity="0.16" />
        <stop offset="0.12" stopColor="#ffffff" stopOpacity="0.04" />
        <stop offset="0.5" stopColor="#ffffff" stopOpacity="0.01" />
        <stop offset="0.82" stopColor="#ffffff" stopOpacity="0.05" />
        <stop offset="0.93" stopColor="#ffffff" stopOpacity="0.14" />
        <stop offset="1" stopColor="#ffffff" stopOpacity="0.04" />
      </linearGradient>
      <radialGradient id={`${id}-halo`} gradientUnits="userSpaceOnUse" cx={cx} cy={baseline - size * 0.36} r={w * 0.8}>
        <stop offset="0" stopColor={glow.glow} stopOpacity="0.32" />
        <stop offset="1" stopColor={glow.glow} stopOpacity="0" />
      </radialGradient>
      <linearGradient id={`${id}-socket`} gradientUnits="userSpaceOnUse" x1={x} y1="0" x2={x + w} y2="0">
        <stop offset="0" stopColor="#0d0d0d" />
        <stop offset="0.35" stopColor="#3b3b3b" />
        <stop offset="0.6" stopColor="#1f1f1f" />
        <stop offset="1" stopColor="#0a0a0a" />
      </linearGradient>
      <path d={glass} fill="#1a120d" opacity={0.55} />
      {mesh}
      {COLD.filter((d) => d !== digit).slice(0, 3).map((d) => (
        <text x={cx} y={baseline} fontFamily="FiraGO" fontWeight={300} fontSize={size} fill="none" stroke="#6b4a33" strokeWidth={Math.max(0.6, w * 0.008)} textAnchor="middle" opacity={0.55}>
          {d}
        </text>
      ))}
      {lit ? <rect x={x} y={y} width={w} height={h} fill={`url(#${id}-halo)`} /> : null}
      {lit ? <text x={cx} y={baseline} fontFamily="FiraGO" fontWeight={300} fontSize={size} fill="none" stroke={glow.glow} strokeWidth={size * 0.16} strokeLinejoin="round" textAnchor="middle" opacity={0.12}>
        {digit}
      </text> : null}
      {lit ? <text x={cx} y={baseline} fontFamily="FiraGO" fontWeight={300} fontSize={size} fill="none" stroke={glow.glow} strokeWidth={size * 0.07} strokeLinejoin="round" textAnchor="middle" opacity={0.3}>
        {digit}
      </text> : null}
      {lit ? <text x={cx} y={baseline} fontFamily="FiraGO" fontWeight={300} fontSize={size} fill={glow.core} stroke={glow.edge} strokeWidth={size * 0.018} textAnchor="middle">
        {digit}
      </text> : null}
      <path d={glass} fill={`url(#${id}-glass)`} />
      <path d={glass} fill="none" stroke="#ffffff" strokeWidth={Math.max(1, w * 0.012)} opacity={0.18} />
      <rect x={x - w * 0.04} y={y + h - h * 0.02} width={w * 1.08} height={h * 0.13} rx={w * 0.05} fill={`url(#${id}-socket)`} />
      <rect x={x + w * 0.1} y={y + h + h * 0.02} width={w * 0.8} height={h * 0.012} fill="#c9a25b" opacity={0.5} />
    </g>
  )
}

function neonDot(cx: number, cy: number, r: number, glow: any) {
  return (
    <g>
      <circle cx={cx} cy={cy} r={r * 3.2} fill={glow.glow} opacity={0.1} />
      <circle cx={cx} cy={cy} r={r * 1.8} fill={glow.glow} opacity={0.25} />
      <circle cx={cx} cy={cy} r={r} fill={glow.core} />
    </g>
  )
}

export function get(app: FrameOSApp, context: FrameOSContext) {
  const W = context.imageWidth ?? app.frame.width
  const H = context.imageHeight ?? app.frame.height
  const glow = GLOWS[app.config.glow] || GLOWS.orange
  const twelve = app.config.clock === '12h'
  const showDate = String(app.config.showDate) !== 'false'
  const now = new Date()
  frameos.setNextSleep(secondsToNextMinute(now))
  const hours = now.getHours()
  // A 12-hour clock leaves the first tube dark rather than lighting a 0.
  const hourDigits = twelve ? String(hours % 12 || 12).padStart(2, ' ') : two(hours)
  const digits = hourDigits + two(now.getMinutes())

  const portrait = H > W * 1.1
  const u = Math.min(W, H) / 100
  // The walnut base the tubes stand on, and the plate on it.
  const baseH = H * (portrait ? 0.16 : 0.22)
  const baseY = H - baseH
  const pad = u * 6
  const tubes = []
  let dots = []
  if (!portrait) {
    const colon = u * 7
    const gap = u * 2.2
    const tw = Math.min((W - pad * 2 - colon - gap * 2) / 4, ((baseY - pad) * 0.86) / 1.95)
    const th = tw * 1.95
    const total = tw * 4 + gap * 2 + colon
    let x = (W - total) / 2
    const y = baseY - th * 1.08
    for (let i = 0; i < 4; i++) {
      tubes.push(tube(`t${i}`, x, y, tw, th, digits[i], glow))
      x += tw + (i === 1 ? colon : gap)
      if (i === 1) {
        const cx = x - colon / 2 - gap / 2
        dots = [neonDot(cx, y + th * 0.42, u * 0.9, glow), neonDot(cx, y + th * 0.62, u * 0.9, glow)]
      }
    }
  } else {
    const gap = u * 3
    const tw = Math.min((W - pad * 2 - gap) / 2, ((baseY - pad * 2) / 2 - gap) / 2.1)
    const th = tw * 1.95
    const startX = (W - tw * 2 - gap) / 2
    const rowY = [baseY - th * 2.25, baseY - th * 1.08]
    for (let i = 0; i < 4; i++) {
      tubes.push(tube(`t${i}`, startX + (i % 2) * (tw + gap), rowY[Math.floor(i / 2)], tw, th, digits[i], glow))
    }
  }

  const plateText = `${WEEKDAYS[now.getDay()]} ${now.getDate()} ${MONTHS[now.getMonth()]}`.toUpperCase() + (twelve ? (hours < 12 ? ' · AM' : ' · PM') : '')
  const plateSize = Math.min(baseH * 0.2, (W * 0.6) / (plateText.length * 0.62))
  const plateW = plateText.length * plateSize * 0.66 + u * 8
  const plateH = plateSize * 2
  const plateX = (W - plateW) / 2
  const plateY = baseY + (baseH - plateH) / 2 + baseH * 0.08

  // A few lines of grain across the walnut.
  const grain = []
  for (let k = 0; k < 9; k++) {
    const gy = baseY + baseH * (0.12 + k * 0.1)
    grain.push(
      <path
        d={`M0 ${gy.toFixed(1)} C${(W * 0.3).toFixed(1)} ${(gy - baseH * 0.05 * ((k % 3) - 1)).toFixed(1)} ${(W * 0.6).toFixed(1)} ${(gy + baseH * 0.04).toFixed(1)} ${W} ${(gy - baseH * 0.02).toFixed(1)}`}
        fill="none"
        stroke="#1a0f08"
        strokeWidth={u * 0.25}
        opacity={0.35}
      />,
    )
  }

  return (
    <svg viewBox={`0 0 ${W} ${H}`} width={W} height={H}>
      <radialGradient id="room" gradientUnits="userSpaceOnUse" cx={W / 2} cy={baseY} r={Math.max(W, H) * 0.7}>
        <stop offset="0" stopColor="#2a1c14" />
        <stop offset="1" stopColor="#0b0806" />
      </radialGradient>
      <linearGradient id="walnut" gradientUnits="userSpaceOnUse" x1="0" y1={baseY} x2="0" y2={H}>
        <stop offset="0" stopColor="#6b4428" />
        <stop offset="0.08" stopColor="#4a2c18" />
        <stop offset="1" stopColor="#2a180c" />
      </linearGradient>
      <radialGradient id="spill" gradientUnits="userSpaceOnUse" cx={W / 2} cy={baseY} r={W * 0.45}>
        <stop offset="0" stopColor={glow.glow} stopOpacity="0.22" />
        <stop offset="1" stopColor={glow.glow} stopOpacity="0" />
      </radialGradient>
      <linearGradient id="brass" gradientUnits="userSpaceOnUse" x1="0" y1={plateY} x2="0" y2={plateY + plateH}>
        <stop offset="0" stopColor="#e7c983" />
        <stop offset="0.5" stopColor="#b88d45" />
        <stop offset="1" stopColor="#8a6328" />
      </linearGradient>
      <rect width={W} height={H} fill="url(#room)" />
      <rect x={0} y={baseY} width={W} height={baseH} fill="url(#walnut)" />
      {grain}
      <rect x={0} y={baseY} width={W} height={Math.max(1, u * 0.4)} fill="#a5714a" opacity={0.6} />
      <rect x={0} y={baseY} width={W} height={baseH} fill="url(#spill)" />
      {tubes}
      {dots}
      {showDate ? (
        <g>
          <rect x={plateX} y={plateY} width={plateW} height={plateH} rx={plateH * 0.18} fill="url(#brass)" />
          <rect x={plateX + u * 0.6} y={plateY + u * 0.6} width={plateW - u * 1.2} height={plateH - u * 1.2} rx={plateH * 0.14} fill="none" stroke="#5c3f15" strokeWidth={u * 0.2} opacity={0.6} />
          <circle cx={plateX + u * 2} cy={plateY + plateH / 2} r={u * 0.6} fill="#5c3f15" opacity={0.7} />
          <circle cx={plateX + plateW - u * 2} cy={plateY + plateH / 2} r={u * 0.6} fill="#5c3f15" opacity={0.7} />
          <text x={W / 2} y={plateY + plateH / 2 + plateSize * 0.36} fontFamily="FiraGO" fontSize={plateSize} fill="#3d2a0e" textAnchor="middle">
            {plateText}
          </text>
        </g>
      ) : null}
    </svg>
  )
}

