// Words and numbers for times and dates. A JS app's Date is in the frame's
// time zone.

export const WEEKDAYS = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday']
export const MONTHS = [
  'January', 'February', 'March', 'April', 'May', 'June',
  'July', 'August', 'September', 'October', 'November', 'December',
]

export function two(value: number) {
  return value < 10 ? '0' + value : '' + value
}

// "14:05", or "2:05 pm" on a 12-hour clock.
export function timeText(hours: number, minutes: number, twelveHour: boolean) {
  if (twelveHour) {
    return (hours % 12 || 12) + ':' + two(minutes) + (hours < 12 ? ' am' : ' pm')
  }
  return two(hours) + ':' + two(minutes)
}

export function clockOf(date: Date, twelveHour: boolean) {
  return timeText(date.getHours(), date.getMinutes(), twelveHour)
}

// Seconds until the next minute starts, so a clock draws on the minute.
export function secondsToNextMinute(date: Date) {
  return Math.max(1, 60 - date.getSeconds())
}
